using namespace std;
struct P{double x,y;};using Poly=vector<P>;
struct Box{double x0=1e100,y0=1e100,x1=-1e100,y1=-1e100;void add(P p){x0=min(x0,p.x);y0=min(y0,p.y);x1=max(x1,p.x);y1=max(y1,p.y);}bool hit(const Box&b)const{return x1>=b.x0-1e-9&&b.x1>=x0-1e-9&&y1>=b.y0-1e-9&&b.y1>=y0-1e-9;}};
Box bounds(const Poly&p){Box b;for(auto v:p)b.add(v);return b;}
double area(const Poly&p){double a=0;for(int i=0;i<(int)p.size();i++){auto x=p[i],y=p[(i+1)%p.size()];a+=x.x*y.y-y.x*x.y;}return a*.5;}
Poly clean(Poly p){Poly q;for(auto a:p)if(q.empty()||hypot(a.x-q.back().x,a.y-q.back().y)>1e-9)q.push_back(a);if(q.size()>1&&hypot(q[0].x-q.back().x,q[0].y-q.back().y)<1e-9)q.pop_back();if(q.size()<3||abs(area(q))<1e-9)return{};return q;}
// Exact linear half-plane clipping in projected coordinates, with finite FP tolerance.
Poly clip(const Poly&p,double a,double b,double c){Poly q;if(p.empty())return q;for(int i=0;i<(int)p.size();i++){P x=p[i],y=p[(i+1)%p.size()];double dx=a*x.x+b*x.y+c,dy=a*y.x+b*y.y+c;bool ix=dx>=-1e-10,iy=dy>=-1e-10;if(ix)q.push_back(x);if(ix!=iy){double t=clamp(dx/(dx-dy),0.,1.);q.push_back({x.x+(y.x-x.x)*t,x.y+(y.y-x.y)*t});}}return clean(q);}
array<double,3> side(P a,P b){return{a.y-b.y,b.x-a.x,a.x*b.y-b.x*a.y};}
Poly intersection(Poly p,const Poly&q){for(int i=0;i<(int)q.size()&&!p.empty();i++){auto e=side(q[i],q[(i+1)%q.size()]);p=clip(p,e[0],e[1],e[2]);}return p;}
vector<Poly> subtract(Poly p,const Poly&q){if(q.empty())return{p};vector<Poly> out;for(int i=0;i<(int)q.size()&&!p.empty();i++){auto e=side(q[i],q[(i+1)%q.size()]);auto o=clip(p,-e[0],-e[1],-e[2]);if(!o.empty())out.push_back(std::move(o));p=clip(p,e[0],e[1],e[2]);}return out;}
P center(const Poly&p){P q{0,0};for(auto v:p){q.x+=v.x;q.y+=v.y;}q.x/=p.size();q.y/=p.size();return q;}
struct Tri{bool ink=false;int owner,index;array<double,3>rgb;double alpha,A,B,C,zmax;Poly p;Box box;double z(P p)const{return A*p.x+B*p.y+C;}};
struct Seg{int owner;array<double,3>rgb;P a,b;double za,zb;};
struct Grid{double step=16;int w,h;vector<vector<int>>bins;vector<int>seen;int stamp=0;const vector<Tri>*ts;
Grid(int W,int H,const vector<Tri>&t):w(ceil(W/step)),h(ceil(H/step)),bins(w*h),seen(t.size(),0),ts(&t){for(int k=0;k<(int)t.size();k++){auto b=t[k].box;for(int y=max(0,(int)floor(b.y0/step));y<=min(h-1,(int)floor(b.y1/step));y++)for(int x=max(0,(int)floor(b.x0/step));x<=min(w-1,(int)floor(b.x1/step));x++)bins[y*w+x].push_back(k);}}
vector<int> query(Box b){vector<int>out;++stamp;for(int y=max(0,(int)floor(b.y0/step));y<=min(h-1,(int)floor(b.y1/step));y++)for(int x=max(0,(int)floor(b.x0/step));x<=min(w-1,(int)floor(b.x1/step));x++)for(int k:bins[y*w+x])if(seen[k]!=stamp){seen[k]=stamp;if((*ts)[k].box.hit(b))out.push_back(k);}return out;}};
Poly front_domain(const Tri&u,const Tri&t){double a=u.A-t.A,b=u.B-t.B,c=u.C-t.C;if(abs(a)+abs(b)<1e-11&&abs(c)<1e-8)return u.index<t.index?u.p:Poly{};return clip(u.p,a,b,c-1e-8);}
vector<Poly> visible(const Tri&t,vector<int>cand,const vector<Tri>&ts,bool all){sort(cand.begin(),cand.end(),[&](int a,int b){return ts[a].zmax>ts[b].zmax;});vector<Poly>ps{t.p};for(int k:cand){auto&u=ts[k];if(k==t.index||(!all&&u.alpha<.999999&&!(t.ink&&u.owner==t.owner)))continue;auto mask=front_domain(u,t);if(mask.empty())continue;Box mb=bounds(mask);vector<Poly>next;for(auto&p:ps){if(!bounds(p).hit(mb)){next.push_back(std::move(p));continue;}auto rem=subtract(p,mask);for(auto&q:rem)next.push_back(std::move(q));}ps=std::move(next);if(ps.empty())break;if(ps.size()>100000)throw runtime_error("visibility fragmentation guard");}return ps;}
string colour(array<double,3>c){ostringstream s;s<<hex<<setfill('0');for(double v:c)s<<setw(2)<<clamp((int)lround(v),0,255);return"#"+s.str();}
string path(const Poly&p){ostringstream o;o<<fixed<<setprecision(6);for(int i=0;i<(int)p.size();i++)o<<(i?"L":"M")<<p[i].x<<","<<p[i].y;o<<"Z";return o.str();}
bool pointin(const Poly&p,P a){for(int i=0;i<(int)p.size();i++){auto e=side(p[i],p[(i+1)%p.size()]);if(e[0]*a.x+e[1]*a.y+e[2]<-1e-8)return false;}return true;}
struct Visible{Poly p;int tri;Box box;};struct Cell{Poly p;vector<int> stack;};
vector<Cell> addglass(const vector<Cell>&cells,const Tri&u,const Tri*base,const vector<Tri>&ts){Poly dom=base?clip(u.p,u.A-base->A,u.B-base->B,u.C-base->C-1e-8):u.p;if(dom.empty())return cells;Box box=bounds(dom);vector<Cell>out;for(auto&c:cells){if(!bounds(c.p).hit(box)){out.push_back(c);continue;}Poly inside=intersection(c.p,dom);if(inside.empty()){out.push_back(c);continue;}for(auto&p:subtract(c.p,dom))out.push_back({std::move(p),c.stack});vector<Poly>parts{inside};for(int k:c.stack){auto&v=ts[k];double a=u.A-v.A,b=u.B-v.B,d=u.C-v.C;if(abs(a)+abs(b)<1e-12)continue;vector<Poly>next;for(auto&p:parts){double lo=1e100,hi=-1e100;for(auto q:p){double z=a*q.x+b*q.y+d;lo=min(lo,z);hi=max(hi,z);}if(lo<-1e-8&&hi>1e-8){auto x=clip(p,a,b,d),y=clip(p,-a,-b,-d);if(!x.empty())next.push_back(std::move(x));if(!y.empty())next.push_back(std::move(y));}else next.push_back(std::move(p));}parts=std::move(next);}for(auto&p:parts){auto st=c.stack;st.push_back(u.index);P mid=center(p);sort(st.begin(),st.end(),[&](int a,int b){double x=ts[a].z(mid),y=ts[b].z(mid);return abs(x-y)>1e-7?x<y:a<b;});out.push_back({std::move(p),std::move(st)});}}
if(out.size()>1000000)throw runtime_error("glass arrangement fragmentation guard");return out;}
// Clip t interval to one affine inequality. No sampling/raster visibility decisions.
bool interval(double a,double b,double&lo,double&hi){if(abs(b)<1e-14)return a>=-1e-10;double t=-a/b;if(b>0)lo=max(lo,t);else hi=min(hi,t);return hi-lo>1e-12;}
bool cover(const Tri&t,const Seg&s,double&lo,double&hi,bool depth){lo=0;hi=1;for(int i=0;i<(int)t.p.size();i++){auto e=side(t.p[i],t.p[(i+1)%t.p.size()]);if(!interval(e[0]*s.a.x+e[1]*s.a.y+e[2],e[0]*(s.b.x-s.a.x)+e[1]*(s.b.y-s.a.y),lo,hi))return false;}if(depth&&!interval(t.z(s.a)-s.za-.01,t.A*(s.b.x-s.a.x)+t.B*(s.b.y-s.a.y)-(s.zb-s.za),lo,hi))return false;return hi-lo>1e-12;}
int main(int argc,char**argv){try{if(argc<3||argc>4)return 2;bool inkOnly=argc==4&&string(argv[3])=="ink-only";ifstream in(argv[1]);int W,H,N;array<double,3>bg;in>>W>>H>>bg[0]>>bg[1]>>bg[2]>>N;if(!in || W<4 || H<4 || N<0 || N>2000000)throw runtime_error("invalid scene header");double factor=.5;W/=2;H/=2;vector<Tri>ts;for(int i=0;i<N;i++){Tri t;t.index=ts.size();array<array<double,3>,3>v;in>>t.owner>>t.rgb[0]>>t.rgb[1]>>t.rgb[2]>>t.alpha;for(auto&p:v){in>>p[0]>>p[1]>>p[2];p[0]*=factor;p[1]*=factor;t.p.push_back({p[0],p[1]});}if(!in)throw runtime_error("truncated triangle data");double den=(v[1][0]-v[0][0])*(v[2][1]-v[0][1])-(v[2][0]-v[0][0])*(v[1][1]-v[0][1]);if(abs(den)<1e-10)continue;t.A=((v[1][2]-v[0][2])*(v[2][1]-v[0][1])-(v[2][2]-v[0][2])*(v[1][1]-v[0][1]))/den;t.B=((v[1][0]-v[0][0])*(v[2][2]-v[0][2])-(v[2][0]-v[0][0])*(v[1][2]-v[0][2]))/den;t.C=v[0][2]-t.A*v[0][0]-t.B*v[0][1];t.zmax=max({v[0][2],v[1][2],v[2][2]});if(area(t.p)<0)reverse(t.p.begin(),t.p.end());t.box=bounds(t.p);ts.push_back(t);}int L;double lw;in>>L>>lw;if(!in || L<0 || L>4000000 || !isfinite(lw) || lw<=0)throw runtime_error("invalid line header");lw*=factor;string rest;getline(in,rest);if(rest.find("v2")!=string::npos)getline(in,rest);vector<Seg>lines;for(int i=0;i<L;i++){Seg s;string row;getline(in,row);istringstream r(row);r>>s.owner>>s.rgb[0]>>s.rgb[1]>>s.rgb[2]>>s.a.x>>s.a.y>>s.za>>s.b.x>>s.b.y>>s.zb;if(!r)throw runtime_error("invalid segment row");s.a.x*=factor;s.a.y*=factor;s.b.x*=factor;s.b.y*=factor;lines.push_back(s);}// Generic object-opacity shell: only the nearest surface of a physical owner
// participates in alpha. Rear/internal tessellation is not another material layer.
long long originalTriangleCount=ts.size(),shellParts=0;Grid initialGrid(W,H,ts);vector<Tri>shell;
for(auto&t:ts){if(t.alpha>=.999999){auto u=t;u.index=shell.size();shell.push_back(u);continue;}vector<Poly>ps{t.p};auto cand=initialGrid.query(t.box);
for(int k:cand){auto&u=ts[k];if(k==t.index||u.owner!=t.owner)continue;auto mask=front_domain(u,t);if(mask.empty())continue;vector<Poly>next;for(auto&p:ps){if(!bounds(p).hit(bounds(mask))){next.push_back(p);continue;}for(auto&q:subtract(p,mask))next.push_back(q);}ps=std::move(next);if(ps.empty())break;}
for(auto&p:ps){auto u=t;u.p=p;u.box=bounds(p);u.index=shell.size();shell.push_back(u);shellParts++;}}
ts=std::move(shell);cerr<<"object-shell "<<originalTriangleCount<<" -> "<<ts.size()<<" transparent fragments "<<shellParts<<"\n";
// Turn display strokes into convex vector capsules with a depth plane.
// They join face visibility and source-over composition instead of an RGB-sorted overlay.
Grid faceGrid(W,H,ts);vector<Tri>inkShapes;long long centreVisible=0;const int arcSteps=24;
for(auto&s:lines){Box b;b.add(s.a);b.add(s.b);auto cand=faceGrid.query(b);vector<pair<double,double>>vis{{0,1}};
for(int k:cand){auto&t=ts[k];if(t.alpha<.999999&&t.owner!=s.owner)continue;double lo,hi;if(!cover(t,s,lo,hi,true))continue;vector<pair<double,double>>next;for(auto q:vis){if(hi<=q.first||lo>=q.second)next.push_back(q);else{if(lo>q.first+1e-12)next.push_back({q.first,lo});if(hi<q.second-1e-12)next.push_back({hi,q.second});}}vis=std::move(next);if(vis.empty())break;}
double dx=s.b.x-s.a.x,dy=s.b.y-s.a.y,ll=dx*dx+dy*dy;if(ll<1e-18)continue;double length=sqrt(ll),ux=dx/length,uy=dy/length,nx=-uy,ny=ux,r=lw*.5;
for(auto v:vis){P a{s.a.x+dx*v.first,s.a.y+dy*v.first},b{s.a.x+dx*v.second,s.a.y+dy*v.second};Poly p;
p.push_back({a.x+nx*r,a.y+ny*r});p.push_back({b.x+nx*r,b.y+ny*r});
if(v.second>1-1e-10){for(int j=1;j<=arcSteps;j++){double q=3.141592653589793*j/arcSteps;p.push_back({b.x+(nx*cos(q)+ux*sin(q))*r,b.y+(ny*cos(q)+uy*sin(q))*r});}}else p.push_back({b.x-nx*r,b.y-ny*r});
p.push_back({a.x-nx*r,a.y-ny*r});if(v.first<1e-10){for(int j=1;j<arcSteps;j++){double q=3.141592653589793*j/arcSteps;p.push_back({a.x+(-nx*cos(q)-ux*sin(q))*r,a.y+(-ny*cos(q)-uy*sin(q))*r});}}
p=clean(p);if(p.empty())continue;if(area(p)<0)reverse(p.begin(),p.end());Tri t;t.ink=true;t.owner=s.owner;t.rgb=s.rgb;t.alpha=1;t.p=p;t.box=bounds(p);t.A=(s.zb-s.za)*dx/ll;t.B=(s.zb-s.za)*dy/ll;t.C=s.za-t.A*s.a.x-t.B*s.a.y+.02;t.zmax=-1e100;for(auto q:p)t.zmax=max(t.zmax,t.z(q));inkShapes.push_back(t);centreVisible++;}}
for(int i=0;i<(int)inkShapes.size();i++)inkShapes[i].index=i;cerr<<"depth-tested vector ink capsules "<<centreVisible<<"\n";
Grid grid(W,H,ts);map<string,string>opaque;vector<Visible>op,top;long long inputT=ts.size();if(!inkOnly)for(auto&t:ts){auto cand=grid.query(t.box);auto ps=visible(t,cand,ts,t.alpha<.999999);for(auto&p:ps){if(t.alpha>=.999999){opaque[colour(t.rgb)]+=path(p);op.push_back({p,t.index,bounds(p)});}else top.push_back({p,t.index,bounds(p)});}if(t.index%20000==0)cerr<<"visibility "<<t.index<<"/"<<ts.size()<<" opaque "<<op.size()<<" glass "<<top.size()<<"\n";}
cerr<<"visible opaque "<<op.size()<<" top glass "<<top.size()<<"\n";
// Grid over visible opaque fragments, used only to seed the exact glass cells.
int nx=ceil(W/16.),ny=ceil(H/16.);vector<vector<int>> ob(nx*ny);for(int i=0;i<(int)op.size();i++){auto b=op[i].box;for(int y=max(0,(int)floor(b.y0/16));y<=min(ny-1,(int)floor(b.y1/16));y++)for(int x=max(0,(int)floor(b.x0/16));x<=min(nx-1,(int)floor(b.x1/16));x++)ob[y*nx+x].push_back(i);}map<string,pair<vector<pair<string,double>>,string>>glass;long long cellsN=0;int gi=0;
for(auto&t:top){set<int>ids;auto box=t.box;for(int y=max(0,(int)floor(box.y0/16));y<=min(ny-1,(int)floor(box.y1/16));y++)for(int x=max(0,(int)floor(box.x0/16));x<=min(nx-1,(int)floor(box.x1/16));x++)for(int k:ob[y*nx+x])if(op[k].box.hit(box))ids.insert(k);vector<pair<Poly,int>>bases;vector<Poly>remaining{t.p};for(int k:ids){auto&u=op[k];auto p=intersection(t.p,u.p);if(!p.empty())bases.push_back({p,u.tri});vector<Poly>next;for(auto&q:remaining){if(!bounds(q).hit(u.box)){next.push_back(std::move(q));continue;}for(auto&r:subtract(q,u.p))next.push_back(std::move(r));}remaining=std::move(next);}for(auto&p:remaining)bases.push_back({p,-1});auto candidates=grid.query(box);vector<int>gc;for(int k:candidates)if(ts[k].alpha<.999999)gc.push_back(k);
for(auto&base:bases){vector<Cell>cells{{base.first,{}}};for(int k:gc)cells=addglass(cells,ts[k],base.second<0?nullptr:&ts[base.second],ts);for(auto&cell:cells){P mid=center(cell.p);vector<int>st;set<int>seenOwners;for(auto it=cell.stack.rbegin();it!=cell.stack.rend();++it){int k=*it;if(seenOwners.insert(ts[k].owner).second)st.push_back(k);}reverse(st.begin(),st.end());/*for(int k:cell.stack){auto&u=ts[k];double z=u.z(mid);if(u.owner==owner&&abs(z-last)<1e-7)continue;st.push_back(k);last=z;owner=u.owner;}*/vector<pair<string,double>>ops{{base.second<0?colour(bg):colour(ts[base.second].rgb),1}};for(int k:st){auto&u=ts[k];string col=colour(u.rgb);if(ops.size()>1&&ops.back().first==col)ops.back().second=1-(1-ops.back().second)*(1-u.alpha);else ops.push_back({col,u.alpha});}ostringstream key;key<<setprecision(12);for(auto&q:ops)key<<q.first<<":"<<q.second<<";";auto&g=glass[key.str()];g.first=ops;g.second+=path(cell.p);cellsN++;}}if(++gi%100==0)cerr<<"glass arrangement "<<gi<<"/"<<top.size()<<" cells "<<cellsN<<"\n";}
map<string,string>compositedInk;long long inkCells=0;Grid inkGrid(W,H,inkShapes);
for(auto&t:inkShapes){auto inkCand=inkGrid.query(t.box);inkCand.erase(remove_if(inkCand.begin(),inkCand.end(),[&](int k){return inkShapes[k].owner==t.owner&&inkShapes[k].rgb==t.rgb;}),inkCand.end());auto ps=visible(t,inkCand,inkShapes,true);auto cand=grid.query(t.box);vector<int>gc;
for(int k:cand){auto&u=ts[k];if(u.owner==t.owner)continue;if(u.alpha<.999999){gc.push_back(k);continue;}auto mask=front_domain(u,t);if(mask.empty())continue;vector<Poly>next;for(auto&p:ps){if(!bounds(p).hit(u.box)){next.push_back(p);continue;}for(auto&q:subtract(p,mask))next.push_back(q);}ps=std::move(next);if(ps.empty())break;}
for(auto&p:ps){vector<Cell>cells{{p,{}}};for(int k:gc)cells=addglass(cells,ts[k],&t,ts);for(auto&c:cells){vector<int>st;set<int>owners;for(auto it=c.stack.rbegin();it!=c.stack.rend();++it)if(owners.insert(ts[*it].owner).second)st.push_back(*it);reverse(st.begin(),st.end());auto col=t.rgb;for(int k:st)for(int j=0;j<3;j++)col[j]=ts[k].rgb[j]*ts[k].alpha+col[j]*(1-ts[k].alpha);compositedInk[colour(col)]+=path(c.p);inkCells++;}}}
cerr<<"depth-composited ink cells "<<inkCells<<" colours "<<compositedInk.size()<<"\n";
map<string,string>inks,rounded;map<string,set<pair<double,double>>>caps;long long segmentsN=centreVisible;
ofstream out(argv[2]);out<<"<svg xmlns=\"http://www.w3.org/2000/svg\" xmlns:xlink=\"http://www.w3.org/1999/xlink\" width=\""<<W/2.<<"pt\" height=\""<<H/2.<<"pt\" viewBox=\"0 0 "<<W<<" "<<H<<"\">\n<title>Brick Blueprint vector illustration</title>\n<rect width=\""<<W<<"\" height=\""<<H<<"\" fill=\""<<colour(bg)<<"\"/>\n<g id=\"opaque-visible-faces\">\n";for(auto&q:opaque)out<<"<path fill=\""<<q.first<<"\" d=\""<<q.second<<"\"/>\n";out<<"</g>\n<defs>\n";int id=0;for(auto&q:glass)out<<"<path id=\"g"<<id++<<"\" d=\""<<q.second.second<<"\"/>\n";out<<"</defs>\n<g id=\"ordered-glass-cells\">\n";id=0;for(auto&q:glass){out<<"<g>";for(auto&op:q.second.first)out<<"<use xlink:href=\"#g"<<id<<"\" fill=\""<<op.first<<"\" fill-opacity=\""<<setprecision(12)<<op.second<<"\"/>";id++;out<<"</g>\n";}out<<"</g>\n<g id=\"depth-composited-ink\">\n";for(auto&q:compositedInk)out<<"<path fill=\""<<q.first<<"\" d=\""<<q.second<<"\"/>\n";out<<"</g>\n<g id=\"depth-clipped-ink\" fill=\"none\" stroke-width=\""<<lw<<"\" stroke-linecap=\"butt\" stroke-linejoin=\"round\">\n";for(auto&q:inks)out<<"<path stroke=\""<<q.first<<"\" d=\""<<q.second<<"\"/>\n";out<<"</g>\n<g id=\"original-endpoint-round-ink\" fill=\"none\" stroke-width=\""<<lw<<"\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\n";for(auto&q:rounded)out<<"<path stroke=\""<<q.first<<"\" d=\""<<q.second<<"\"/>\n";out<<"</g>\n<g id=\"original-endpoint-caps\">\n";for(auto&q:caps)for(auto p:q.second)out<<"<circle fill=\""<<q.first<<"\" cx=\""<<fixed<<setprecision(6)<<p.first<<"\" cy=\""<<p.second<<"\" r=\""<<lw*.5<<"\"/>\n";out<<"</g>\n</svg>\n";ofstream stats(string(argv[2])+".json");stats<<"{\"input_triangles\":"<<N<<",\"nondegenerate_projected_triangles\":"<<inputT<<",\"visible_opaque_fragments\":"<<op.size()<<",\"top_glass_fragments\":"<<top.size()<<",\"glass_arrangement_cells\":"<<cellsN<<",\"opaque_colour_groups\":"<<opaque.size()<<",\"glass_stack_groups\":"<<glass.size()<<",\"ink_colour_groups\":"<<inks.size()<<",\"input_selected_edges\":"<<L<<",\"visible_ink_intervals\":"<<segmentsN<<",\"raster_elements\":0}";cerr<<"COMPLETE\n";return 0;
}catch(exception&e){cerr<<"ERROR "<<e.what()<<"\n";return 1;}}
